export function getGurugramProjectBySlug(slug) {
  if (!slug) return null;
  const clean = String(slug).toLowerCase().trim();
  return GURUGRAM_REGISTRY_PROJECTS.find(p => {
    return p.slug.toLowerCase() === clean || 
           String(p.id) === clean || 
           p.name.toLowerCase().replace(/[^a-z0-9]+/g, '-') === clean;
  }) || null;
}

export const GURUGRAM_ALL_SLUGS = GURUGRAM_REGISTRY_PROJECTS.map(p => p.slug);

export const GURUGRAM_PROJECT_COORDINATES = Object.fromEntries(
  GURUGRAM_REGISTRY_PROJECTS.map(p => [
    p.slug,
    {
      lat: p.lat,
      lng: p.lng,
      locality: p.locality,
      city: "gurugram",
      cityName: "Gurugram",
      propertyType: p.type || "Apartment",
      verified: true
    }
  ])
);
